event) {\n                          _vm.acceptAll()\n                          _vm.close()\n                        }\n                      }\n                    },\n                    [\n                      _vm._v(\n                        \"\\n          \" +\n                          _vm._s(\n                            _vm.$translate(\"Ceres::Template.cookieBarAcceptAll\")\n                          ) +\n                          \"\\n        \"\n                      )\n                    ]\n                  ),\n                  _vm._v(\" \"),\n                  _c(\n                    \"button\",\n                    {\n                      staticClass: \"btn btn-default btn-block\",\n                      on: {\n                        click: function($event) {\n                          _vm.storeConsents()\n                          _vm.close()\n                        }\n                      }\n                    },\n                    [\n                      _vm._v(\n                        \"\\n          \" +\n                          _vm._s(\n                            _vm.$translate(\"Ceres::Template.cookieBarSave\")\n                          ) +\n                          \"\\n        \"\n                      )\n                    ]\n                  )\n                ])\n              ]\n            ),\n            _vm._v(\" \"),\n            _vm.isExpanded\n              ? _c(\n                  \"div\",\n                  {\n                    staticClass: \"row py-3\",\n                    class: _vm.classes,\n                    style: _vm.styles\n                  },\n                  [\n                    _c(\n                      \"div\",\n                      { staticClass: \"col-12 mb-3\" },\n                      [\n                        _c(\"privacy-settings\", {\n                          attrs: { \"consent-groups\": _vm.consentGroups }\n                        })\n                      ],\n                      1\n                    ),\n                    _vm._v(\" \"),\n                    _c(\"div\", { staticClass: \"col-12 col-md-6\" }, [\n                      _c(\n                        \"a\",\n                        {\n                          staticClass:\n                            \"text-primary text-appearance d-inline-block mb-3\",\n                          attrs: { href: \"#\" },\n                          on: {\n                            click: function($event) {\n                              $event.preventDefault()\n                              $event.stopPropagation()\n                              _vm.isExpanded = false\n                            }\n                          }\n                        },\n                        [\n                          _vm._v(\n                            _vm._s(\n                              _vm.$translate(\"Ceres::Template.cookieBarBack\")\n                            )\n                          )\n                        ]\n                      )\n                    ]),\n                    _vm._v(\" \"),\n                    _c(\"div\", { staticClass: \"col-6 col-md-3\" }, [\n                      _c(\n                        \"button\",\n                        {\n                          staticClass:\n                            \"btn btn-block btn-primary btn-appearance\",\n                          on: {\n                            click: function($event) {\n                              _vm.acceptAll()\n                              _vm.close()\n                            }\n                          }\n                        },\n                        [\n                          _vm._v(\n                            \"\\n          \" +\n                              _vm._s(\n                                _vm.$translate(\n                                  \"Ceres::Template.cookieBarAcceptAll\"\n                                )\n                              ) +\n                      