-switch custom-control-appearance d-md-inline-block mr-3\"\n                :key=\"consentGroup.key\"\n              >\n                <input\n                  type=\"checkbox\"\n                  class=\"custom-control-input\"\n                  :id=\"_uid + '-group-' + consentGroup.key\"\n                  :disabled=\"consentGroup.necessary\"\n                  :checked=\"\n                    isConsented(consentGroup.key) || consentGroup.necessary\n                  \"\n                  @change=\"toggleConsent(consentGroup.key)\"\n                />\n                <label\n                  class=\"custom-control-label\"\n                  :for=\"_uid + '-group-' + consentGroup.key\"\n                >\n                  <template v-if=\"consentGroup.label.length > 0\">\n                    {{ consentGroup.label }}\n                  </template>\n                  <template v-else>\n                    {{\n                      $translate(\"Ceres::Template.privacySettingsDefaultGroup\")\n                    }}\n                  </template>\n                </label>\n              </span>\n            </template>\n\n            <a\n              href=\"#\"\n              class=\"text-primary text-appearance d-block d-md-inline-block\"\n              @click.prevent.stop=\"isExpanded = true\"\n              >{{ $translate(\"Ceres::Template.cookieBarMoreSettings\") }}</a\n            >\n          </div>\n        </div>\n        <div class=\"p-3 w-100\">\n          <button\n            class=\"btn btn-primary btn-block btn-appearance\"\n            @click=\"\n              acceptAll();\n              close();\n            \"\n          >\n            {{ $translate(\"Ceres::Template.cookieBarAcceptAll\") }}\n          </button>\n          <button\n            class=\"btn btn-default btn-block\"\n            @click=\"\n              storeConsents();\n              close();\n            \"\n          >\n            {{ $translate(\"Ceres::Template.cookieBarSave\") }}